from pathlib import Path
import hashlib
P=Path(__file__).resolve().parents[1]
base='/birds_Astorp-preview'
style='style.e9efe1ea1d8f0683abe513ee83aacb1ea4cbf2b4ae4048edacbbdc43188889df.css'
nav=[('progress','/','Kommunens fågelår'),('reporters','/kommun/','Rapportörer'),('first','/forstafynd/','Årets förstafynd')]
def version(path):
 return hashlib.sha256((P/path).read_bytes()).hexdigest()[:16]
def page(kind,title,intro,body):
 links=''.join(f'<a href="{base}{url}"'+(' aria-current="page"' if key==kind else '')+f'>{name}</a>' for key,url,name in nav)
 return f'''<!doctype html><html lang="sv"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; style-src 'self' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self'; script-src 'self'; connect-src 'self' https://sosgeo.artdata.slu.se; base-uri 'none'; form-action 'none'"><title>{title} · Åstorps fåglar</title><link rel="icon" href="{base}/favicon.ico"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Lora:ital,wght@0,400;0,700;1,400&display=swap" rel="stylesheet"><link rel="stylesheet" href="{base}/css/{style}"><link rel="stylesheet" href="{base}/css/municipal-preview.css?v={version('css/municipal-preview.css')}"></head><body data-view="{kind}"><a class="skip-link" href="#main-content">Hoppa till innehåll</a><div class="preview-strip">Offentlig förhandsvisning · uppdaterad 29 oktober 2026 · inte den ordinarie sajten</div><header class="portal-top"><a class="portal-brand" href="{base}/">Fågelåret i Åstorp</a><a href="https://astorpsfaglar.se/">Till den ordinarie fågelårsboken ↗</a></header><main class="portal" id="main-content"><div class="portal-logo"><img src="{base}/images/logo-fagelaret-2026.png" alt="Ett år med fåglar – Åstorp 2026" width="900" height="250"></div><nav class="portal-nav" aria-label="Kommunens fåglar">{links}</nav><p class="eyebrow">Åstorps kommun · alla observatörer</p><h1>{title}</h1><p class="intro">{intro}</p>{body}<div class="portal-refresh"><button id="refresh-data" type="button">Hämta senaste fynd</button><p class="portal-small">Offentliga fynd hämtas från SLU. Ingen inloggning krävs.</p></div><details><summary>Om underlaget och förhandsvisningen</summary><p id="source-detail">Kommunstatistiken behöver ett komplett, kontrollerat urval av offentliga fynd. Saknade data visas aldrig som noll. Håkans personliga årslista används inte som kommunlista.</p><p>Taxonomi: <a href="https://www.avilist.org/checklist/v2026/">AviList v2026, 20 oktober 2026</a>. Gråkråka och svartkråka räknas som en art. Tamduva ingår i klippduva enligt det befintliga listundantaget, inte som ytterligare art. Artfaktas ID används för källkoppling; AviList styr artindelningen.</p><p>Källa: <a href="https://github.com/biodiversitydata-se/SOS/blob/master/Docs/Observation.md">SLU:s dokumentation av observationsdata</a>. Hämtningen är offentlig och kräver ingen nyckel. Enighet mellan antalskontroller innebär inte ett atomiskt databasögonblick.</p><p>Rapporter är inte en fullständig inventering av fågellivet. Skyddade fynd ingår inte. Ett fynd som saknas i ett urval betyder inte att arten saknas i kommunen.</p><p>Rapportör och observatör är olika roller. Ett visningsnamn räcker inte för säker personidentifiering. Inga privata koordinater visas här.</p></details><p class="portal-footer">Tre separata perspektiv på samma fågelår. <a href="{base}/prototyper/">Version och avgränsningar</a></p></main><script src="{base}/js/municipal-preview-data.js?v={version('js/municipal-preview-data.js')}"></script><script src="{base}/js/municipal-preview-live.js?v={version('js/municipal-preview-live.js')}"></script><script src="{base}/js/municipal-preview-ui.js?v={version('js/municipal-preview-ui.js')}" defer></script></body></html>'''
controls='''<div class="portal-controls"><label>Jämför till och med<input type="date" id="cutoff" value="2026-10-29" min="2026-01-01" max="2026-10-29"></label></div><div class="portal-status" id="data-status" role="status">Läser källstatus …</div>'''
progress=controls+'''<div class="portal-grid"><section class="portal-panel soft"><h2>Arter hittills i år</h2><div class="portal-metric" id="current-count">—</div><p class="portal-small">Unika arter i det kontrollerade kommunurvalet, oavsett rapportör.</p></section><section class="portal-panel"><h2>Samma tid förra året</h2><div class="portal-metric" id="previous-count">—</div><p class="portal-small" id="difference">Jämförelsen kräver samma täckning för båda åren.</p></section><section class="portal-panel"><h2>Nytt i den offentliga historiken?</h2><div id="history-result"><p class="portal-small">Jämför årets arter med äldre offentliga Artportalenfynd. Detta visar inte säkert kommunens första fynd någonsin.</p></div><button id="check-history" type="button">Kontrollera äldre fynd</button><p class="portal-small" id="history-status" role="status">Historiken är inte hämtad i denna vy.</p></section><section class="portal-panel wide"><h2>Hur ligger fågelåret till?</h2><p class="portal-small">Antal arter fram till samma kalenderdatum. Inte en jämförelse med föregående helår.</p><div id="year-bars" class="year-bars"><p class="portal-empty">Jämförbara årsdata saknas ännu.</p></div></section><section class="portal-panel"><h2>Nytt jämfört med förra året</h2><p class="portal-small">Rapporterat i år, men inte i föregående års hela underlag.</p><ul id="new-full"><li>Kan inte avgöras ännu.</li></ul></section><section class="portal-panel"><h2>Tidigare ute i år</h2><p class="portal-small">Rapporterat i år, men inte vid samma tid förra året.</p><ul id="new-cutoff"><li>Kan inte avgöras ännu.</li></ul></section><section class="portal-panel"><h2>Ännu inte rapporterat i år</h2><p class="portal-small">Fanns vid samma tid förra året, men saknas i årets underlag.</p><ul id="missing"><li>Kan inte avgöras ännu.</li></ul></section></div>'''
reporters='''<div class="portal-controls"><label>Period<select id="reporter-period"><option value="2026">2026</option><option value="all">Alla tider</option></select></label></div><div class="portal-status" role="status" id="data-status">Personkopplad statistik är ännu inte verifierad.</div><section class="portal-panel"><h2>Vem har rapporterat flest arter?</h2><p class="portal-small">En art räknas en gång per rapportör. Andelen avser kommunens unika arter under exakt samma period.</p><div class="table-wrap"><table><caption class="portal-small" id="reporter-caption">Årets rapportörstatistik · 2026</caption><thead><tr><th scope="col">Rapportör</th><th scope="col">Arter</th><th scope="col">Andel av kommunens arter</th></tr></thead><tbody><tr><td colspan="3" class="portal-empty" id="reporter-empty">Inga placeringar visas innan identitet, täckning och källans användningsvillkor är verifierade.</td></tr></tbody></table></div></section><div class="portal-grid"><section class="portal-panel wide soft"><h2>Rapportering är inte samma sak som observation</h2><p>En person kan rapportera en fågel som flera har sett. Vyn gäller rapportörer; den utser inte vem som har sett flest arter.</p><p class="portal-small">Rapportörernas artlistor överlappar. Därför kan deras andelar tillsammans överstiga 100 procent. ”Alla tider” behöver ett historiskt underlag med tydlig startpunkt.</p></section></div>'''
first='''<div class="portal-controls"><label>År<select id="first-year"><option value="2026">2026</option><option value="2025">2025</option></select></label><label>Sök art<input type="search" id="species-search" placeholder="Till exempel salskrake"></label></div><div class="portal-status" id="data-status" role="status">Läser källstatus …</div><section class="portal-panel"><h2>När kom årets första fynd?</h2><p class="portal-small">Tidigaste fynddatum i kommunurvalet. Underarter räknas till art enligt AviList v2026. Samma dag kan ha flera förstafynd; utan klockslag utses ingen ensam först. ”Visa källans namn” hämtar krediteringen för just fyndet. Namntexter slås inte ihop till personidentiteter.</p><div class="table-wrap"><table><caption class="portal-small" id="first-caption">Årets förstafynd · 2026</caption><thead><tr><th scope="col">Art</th><th scope="col">Första fynddatum</th><th scope="col">Källans namntext</th><th scope="col">Källa</th></tr></thead><tbody id="first-body"><tr><td colspan="4" class="portal-empty">Fyndunderlaget är ännu inte verifierat.</td></tr></tbody></table></div></section>'''
for kind,title,intro,body,path in [('progress','Kommunens fågelår','Hur utvecklas fågelåret i Åstorp? Följ kommunens samlade artlista och jämför med tidigare år.',progress,'index.html'),('reporters','Rapportörerna bakom fynden','Ett eget perspektiv på bidragen till kommunens fågelkunskap – i år och över tid.',reporters,'kommun/index.html'),('first','Årets första fynd','En art, ett första datum och de rapporter som ligger bakom. Här följer vi hur årets artlista växer.',first,'forstafynd/index.html')]:
 p=P/path;p.parent.mkdir(parents=True,exist_ok=True);html=page(kind,title,intro,body)
 if kind=='reporters':html=html.replace('Offentliga fynd hämtas från SLU. Ingen inloggning krävs.','Rapportörsstatistiken kräver en verifierad källa med stabila person-ID. Den offentliga WFS-källans namnsträngar räcker inte.')
 p.write_text(html)
